if(inspectorTab==='audio'||m.type==='audio'||page==='audio'){el.innerHTML+=section('Clip audio',field('Volume','gain',c.gain??1,0,2,.01)+field('Pan','pan',c.pan||0,-1,1,.01)+field('Fade in','fadeIn',c.fadeIn||0,0,Math.min(10,c.duration),.1)+field('Fade out','fadeOut',c.fadeOut||0,0,Math.min(10,c.duration),.1));const track=p.tracks.find(t=>t.id===c.trackId);el.innerHTML+=section('Track equalizer',field('Low shelf','lowEQ',track.lowEQ||0,-24,24,.5,'track')+field('High shelf','highEQ',track.highEQ||0,-24,24,.5,'track'));return;}
