function renderExtra(){const el=$('#page-extra'),c=activeSelected();if(page==='color'){const g={...gradeDefaults(),...c?.grade};el.innerHTML=`<div class="color-workbench"><div><div class="extra-title"><span>Primaries · Color wheels</span><button data-action="reset-grade">Reset</button></div><div class="wheels">${[['Lift','lift',-.3,.3],['Gamma','gamma',.3,2],['Gain','gain',.2,2],['Offset','exposure',-2,2]].map(([label,key,min,max])=>`<div class="wheel"><span>${label}</span><div class="wheel-disc" data-wheel="${key}" title="Drag horizontally to adjust ${label}"></div><input aria-label="${label}" type="range" min="${min}" max="${max}" step=".01" value="${g[key]}" data-property="${key}" data-scope="grade"></div>`).join('')}</div></div><div class="scopes"><span class="small">Scopes <span class="muted">· RGB histogram</span></span><canvas id="histogram" width="256" height="128"></canvas></div></div>`;drawScopes();}else if(page==='fusion'){const nodes=store.project.nodes.filter(n=>n.clipId===c?.id);el.innerHTML=`<div class="extra-title"><span>Nodes <span class="muted">· ${esc(c?.name||'Select a clip')}</span></span><div><button data-add-node="Color">＋ Color</button><button data-add-node="Blur">＋ Blur</button><button data-add-node="Monochrome">＋ Mono</button></div></div><div class="graph">${nodes.length?nodes.map(n=>`<button class="graph-node ${selectedNode===n.id?'active':''} ${n.enabled===false?'off':''}" data-node="${n.id}">${esc(n.type)}<span>${n.enabled===false?'Bypassed':'Connected'}</span></button>`).join(''):'<button class="secondary" data-action="init-graph">Create processing chain</button>'}</div>`;}else if(page==='audio'){el.innerHTML=`<div class="mixer-strips">${store.project.tracks.map(t=>`<div class="mixer-strip"><span>${esc(t.name)}</span><span class="muted small">${((t.gain??1)===0?-Infinity:20*Math.log10(t.gain??1)).toFixed(1)} dB</span><input type="range" aria-label="${esc(t.name)} volume" data-track-gain="${t.id}" min="0" max="2" step=".01" value="${t.gain??1}"><div><button data-track-action="mute" data-id="${t.id}" class="${t.muted?'active':''}">M</button><button data-track-action="solo" data-id="${t.id}" class="${t.solo?'active':''}">S</button></div></div>`).join('')}<div class="mixer-strip"><span>Main bus</span><span class="muted small">Stereo output</span><input type="range" id="master-gain" aria-label="Master gain" min="0" max="1.5" step=".01" value="${library.masterGain}"></div></div>`;}else el.innerHTML='';}
function drawScopes(){const canvas=$('#histogram');if(!canvas)return;try{const bins=renderer.histogram(),x=canvas.getContext('2d');x.clearRect(0,0,256,128);x.strokeStyle='#44404b';for(let i=1;i<4;i++){x.beginPath();x.moveTo(0,i*32);x.lineTo(256,i*32);x.stroke();}bins.forEach((b,n)=>{const max=Math.max(1,...b);x.beginPath();x.moveTo(0,128);b.forEach((v,i)=>x.lineTo(i*2,128-Math.sqrt(v/max)*115));x.lineTo(256,128);x.closePath();x.fillStyle=['#ed747450','#75d59550','#829ee850'][n];x.fill();});}catch{}}
function setPage(value){if(!pages.some(x=>x[0]===value))return;page=value;const extra=$('#workspace').className.split(' ').filter(x=>['no-media','no-inspector','show-media-mobile','inspector-mobile'].includes(x));$('#workspace').className='workspace '+page+' '+extra.join(' ');$('#workspace-label').textContent=(page==='audio'?'AUDIO':page.toUpperCase())+' WORKSPACE';$$('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===page));if(page==='color'||page==='fusion'){if(!selected()){const c=activeSelected();if(c)store.select(c.id);}inspectorTab='video';}if(page==='audio')inspectorTab='audio';if(page==='deliver')renderDeliver();else{if($('#media-panel .media-body')?.dataset.deliver==='true')restorePool();renderMedia();}renderInspector();renderExtra();timeline.render();}
const originalPool=$('#media-panel .media-body').outerHTML;
