async function drawSource(){const m=store.project.media.find(m=>m.id===sourceId);if(!m)return;$('#source-name').textContent='Source · '+m.name;$('#source-tc').textContent=timecode(sourceTime,store.project.fps);$('#source-range').textContent=`${sourceIn.toFixed(1)}–${sourceOut.toFixed(1)}s`;const x=$('#source-canvas').getContext('2d'),w=960,h=540;x.fillStyle='#101317';x.fillRect(0,0,w,h);try{const e=await library.load(m);if(m.type==='title'){x.fillStyle=m.color||'#fff';x.font='45px Georgia';x.textAlign='center';x.fillText(m.text,w/2,h/2);}else if(m.type==='audio'){x.fillStyle='#83bca7';const v=m.waveform||[];v.forEach((a,i)=>x.fillRect(i*w/v.length,h/2-a*150,3,a*300));}else{const el=e.element;if(m.type==='video'){if(Math.abs(el.currentTime-sourceTime)>.1)el.currentTime=sourceTime;el.muted=true;if(sourcePlaying)el.play().catch(()=>{});else el.pause();}const mw=el.videoWidth||el.naturalWidth,mh=el.videoHeight||el.naturalHeight,s=Math.min(w/mw,h/mh);x.drawImage(el,(w-mw*s)/2,(h-mh*s)/2,mw*s,mh*s);}}catch(e){x.fillStyle='#b5aabc';x.textAlign='center';x.font='20px sans-serif';x.fillText(e.message,w/2,h/2);}}
function sourceTick(now){if(sourcePlaying){sourceTime+=(now-sourceLast)/1000;const m=store.project.media.find(m=>m.id===sourceId);if(sourceTime>=(m?.duration||8)){sourceTime=0;sourcePlaying=false;}drawSource();}sourceLast=now;requestAnimationFrame(sourceTick);}requestAnimationFrame(sourceTick);
async function appendMedia(id=sourceId,trackId,start){const m=store.project.media.find(m=>m.id===id);if(!m)return;trackId??=store.project.tracks.find(t=>t.type===(m.type==='audio'?'audio':'video')&&!t.locked&&t.id!=='v2')?.id||store.project.tracks.find(t=>!t.locked)?.id;if(!trackId||store.project.tracks.find(t=>t.id===trackId)?.locked){toast('Choose an unlocked track');return;}const targetTrack=store.project.tracks.find(t=>t.id===trackId);if(targetTrack.type==='audio'&&!['audio','video'].includes(m.type)){toast('Drop picture media onto a video track');return;}const clip=createClip(m,trackId,start??duration(store.project));if(id===sourceId&&sourceOut>sourceIn){clip.in=sourceIn;clip.duration=sourceOut-sourceIn;}store.transact('Append clip',p=>p.clips.push(clip));store.select(clip.id);playback.seek(clip.start);renderInspector();}
async function importFiles(files){let count=0;for(const file of files){if(!/^(video|audio|image)\//.test(file.type)){toast('Unsupported media file: '+file.name);continue;}if(file.size>100*1024*1024){toast('Files larger than 100 MB need to be reduced before cloud upload');continue;}try{toast('Importing '+file.name);const m=await library.metadata(file);sync.pendingMedia.set(m.id,file);store.addMedia(m);sourceId=m.id;sourceIn=0;sourceOut=Math.min(m.duration,8);count++;}catch(e){toast(e.message);}}if(count){poolMode='media';renderMedia();drawSource();playback.invalidate();toast(`${count} media ${count===1?'file':'files'} imported. Double-click to append.`);}}
function addTitle(){const m={id:uid(),name:'Text title',type:'title',text:'Your title',fontSize:80,fontFamily:'Georgia',color:'#ffffff',duration:5};let t=store.project.tracks.find(t=>t.type==='video'&&!t.locked);if(!t)return;const c=createClip(m,t.id,playback.time);store.transact('Add title',p=>{p.media.push(m);p.clips.push(c);});store.select(c.id);inspectorTab='video';renderInspector();}
function applyEffect(effect){if(effect==='title'){addTitle();return;}const c=activeSelected();if(!c){toast('Select a timeline clip first');return;}store.select(c.id);if(effect==='blur'){addNode('Blur');setPage('fusion');return;}store.transact('Apply '+effect,p=>{const clip=p.clips.find(x=>x.id===c.id);if(effect==='fade'){clip.fadeIn=Math.min(1,clip.duration/2);clip.fadeOut=Math.min(1,clip.duration/2);}if(effect==='mono')clip.grade={...clip.grade,saturation:0};if(effect==='cinema')clip.grade={...gradeDefaults(),contrast:1.12,saturation:.78,temperature:-.15,lift:.015,gamma:1.06,vignette:.18};if(effect==='warm')clip.grade={...gradeDefaults(),temperature:.5,saturation:.9,gamma:1.05};});toast('Applied '+effect);}
function addNode(type){const c=activeSelected();if(!c)return;const node={id:uid(),clipId:c.id,type,enabled:true,inputs:[],params:type==='Blur'?{amount:4}:{}};store.transact('Add '+type+' node',p=>{let chain=p.nodes.filter(n=>n.clipId===c.id);if(!chain.length){const input={id:uid(),clipId:c.id,type:'MediaIn',enabled:true,inputs:[]},out={id:uid(),clipId:c.id,type:'MediaOut',enabled:true,inputs:[input.id]};p.nodes.push(input,out);chain=[input,out];}const out=chain.find(n=>n.type==='MediaOut');node.inputs=[...(out?.inputs||[chain.at(-1).id])];if(out)out.inputs=[node.id];const index=out?p.nodes.indexOf(out):p.nodes.length;p.nodes.splice(index,0,node);validateGraph(p.nodes);});selectedNode=node.id;renderExtra();renderInspector();}
async function projectsDialog(){if(browserMode){dialog('Browser project library','<p>Loading projects saved on this device…</p>');try{const d=await sync.list();dialog('Browser project library',`<p>Projects and imported media are stored in this browser. Clearing site data removes them. Download project files and keep the original media for backups.</p>${d.projects.map(p=>`<div class="project-row"><div><strong>${esc(p.name)}</strong><small>${new Date(p.updated_at).toLocaleString()}</small></div><button class="secondary" data-open-project="${esc(p.id)}">Open</button></div>`).join('')||'<p>No saved projects yet.</p>'}`,`<button data-action="new-project">New project</button><button data-action="open-project">Open project file</button><button class="primary" data-action="save">Save current project</button>`);}catch(e){dialog('Browser storage unavailable',`<p>${esc(e.message)}</p><p>Editing still works. Download your project before closing this tab.</p>`,'<button class="primary" data-action="export-project">Download project</button>');}return;}dialog('Project library','<p>Loading your projects…</p>');try{const d=await sync.list();const rows=d.projects.map(p=>`<div class="project-row"><div>${icon('media')}</div><div><strong>${esc(p.name)}</strong><small>${new Date(p.updated_at).toLocaleString()} · ${esc(p.role)}</small></div><button class="secondary" data-open-project="${p.id}">Open</button></div>`).join('');dialog('Project library',`<p>Signed in as ${esc(d.user.name)}</p>${rows||'<p>No saved projects yet.</p>'}<label for="join-code">Join a shared project</label><input id="join-code" placeholder="Paste a collaboration code"><button class="secondary" data-action="join" style="margin-top:10px">Join project</button>`,`<button data-action="new-project">New project</button><button class="primary" data-action="save">Save current project</button>`);}catch(e){dialog('Project library',`<p>${esc(e.message)}</p><p>You can keep editing and download a project file.</p><a href="/signin-with-chatgpt?return_to=/studio/index.html" target="_top" class="primary" style="display:inline-block;padding:9px 15px;border-radius:4px;text-decoration:none">Sign in with ChatGPT</a>`,`<button data-action="open-project">Open project file</button><button class="primary" data-action="export-project">Download project</button>`);}}
async function saveProject(){try{toast('Saving project…');if(!sync.id)await sync.create();else await sync.save();localStorage.setItem(lastProjectKey,sync.id);toast(browserMode?'Project and media saved in this browser':'Project saved');if($('#dialog').open)$('#dialog').close();}catch(e){toast(e.message);}}
async function collaborate(){if(browserMode){if(sync.id)await sync.poll();const notes=sync.last?.comments||[];dialog('Local workspace',`<p>GitHub Pages does not run a collaboration server. This edition saves projects and media on this device. Tabs in the same browser can reopen a saved project and synchronize revision-checked edits every four seconds.</p><p>For multi-user projects, accounts, invitations and cloud media, use the server-backed edition included in the repository.</p>${sync.id?`<label for="comment-text">Review note at ${timecode(playback.time,store.project.fps)}</label><textarea id="comment-text" placeholder="Add a local review note…"></textarea><button class="primary" data-action="post-comment">Save note</button>${notes.map(c=>`<article class="comment"><header><strong>${esc(c.name)}</strong><button data-seek="${c.time/1000}">${timecode(c.time/1000,store.project.fps)}</button></header><p>${esc(c.body)}</p></article>`).join('')}`:'<p>Save your project first to add local review notes.</p>'}`,'<button data-action="export-project">Download project</button><button class="primary" data-action="save">Save locally</button>');return;}if(!sync.id){dialog('Collaborate on this project','<p>Save the project to create a shared workspace with comments, teammate presence, and synchronized edits.</p>','<button data-action="close-dialog">Cancel</button><button class="primary" data-action="save">Save project</button>');return;}await sync.poll();const d=sync.last||{members:[],comments:[]};dialog('Project collaboration',`<p>Project edits sync every four seconds. Changes to different objects merge automatically; competing edits are flagged for review.</p><div class="project-row"><strong>${esc(store.project.name)}</strong><button class="secondary" data-action="invite">Create join code</button></div>${sync.inviteCode?`<label>Collaboration code</label><input readonly value="${esc(sync.inviteCode)}"><p class="small muted">Give this code to someone who already has access to this site.</p>`:''}<label>Project members</label>${d.members.map(m=>`<div class="project-row"><span class="avatar">${esc(m.name.slice(0,1).toUpperCase())}</span><div><strong>${esc(m.name)}</strong><small>${esc(m.role)} · ${Date.now()-m.last_seen<15000?'Online':'Away'}</small></div>${d.role==='owner'&&m.role!=='owner'?`<button class="danger" data-remove-member="${esc(m.user_id)}">Remove</button>`:''}</div>`).join('')}<label for="comment-text">Comment at ${timecode(playback.time,store.project.fps)}</label><textarea id="comment-text" placeholder="Add a review note…"></textarea><button data-action="post-comment" class="primary" style="margin-top:8px">Post comment</button><div>${d.comments.map(c=>`<article class="comment"><header><strong>${esc(c.name)}</strong><button data-seek="${c.time/1000}">${timecode(c.time/1000,store.project.fps)}</button></header><p>${esc(c.body)}</p></article>`).join('')}</div>`);}
function settings(){const p=store.project;dialog('Project settings',`<label>Project name</label><input id="settings-name" value="${esc(p.name)}"><label>Timeline frame rate</label><select id="settings-fps">${[24,25,30,48,50,60].map(f=>`<option ${f===p.fps?'selected':''}>${f}</option>`).join('')}</select><label>Timeline resolution</label><select id="settings-size">${[[1280,720],[1920,1080],[3840,2160],[1080,1920]].map(([w,h])=>`<option value="${w}x${h}" ${w===p.width&&h===p.height?'selected':''}>${w} × ${h}</option>`).join('')}</select><label>Appearance</label><select id="settings-theme"><option value="dark">Dark studio</option><option value="light" ${document.body.dataset.theme==='light'?'selected':''}>Light studio</option></select><p class="small">Changing frame rate keeps clip times in seconds. Source media is unchanged.</p>`,'<button data-action="close-dialog">Cancel</button><button class="primary" data-action="apply-settings">Apply settings</button>');}
async function runRender(){if(renderAbort)return;const width=Number($('#export-size').value);exportOptions={name:$('#export-name').value||store.project.name,width,height:Math.round(width*store.project.height/store.project.width),fps:Number($('#export-fps').value),mimeType:$('#export-format').value,bitrate:Number($('#export-bitrate').value)};renderAbort=new AbortController();renderJob={name:exportOptions.name,status:'Preparing media…',progress:0};renderInspector();$('#media-panel [data-action="render"]').disabled=true;try{const out=await renderVideo(playback,{...exportOptions,signal:renderAbort.signal,onProgress:p=>{renderJob.progress=p;renderJob.status=`Rendering · ${Math.round(p*100)}%`;const progress=$('.render-job progress');if(progress)progress.value=p;const text=$('.render-job p');if(text)text.textContent=renderJob.status;}});renderJob={...renderJob,...out,progress:1,status:'Render complete · '+(out.blob.size/1024/1024).toFixed(1)+' MB'};toast('Render complete — your video is ready');}catch(e){renderJob.status=e.message;toast(e.message);}finally{renderAbort=null;renderInspector();if(page==='deliver')renderDeliver();}}
const actions={
 'play':()=>playback.playing?playback.pause():playback.play(),
 'home':()=>playback.seek(0),'end':()=>playback.seek(duration(store.project)),
 'back':()=>{playback.pause();playback.seek(playback.time-1/store.project.fps);},'forward':()=>{playback.pause();playback.seek(playback.time+1/store.project.fps);},
 'loop':()=>{playback.loop=!playback.loop;$('#loop-button').classList.toggle('active',playback.loop);},
 'undo':()=>store.undo(),'redo':()=>store.redo(),'split':()=>store.split(playback.time),'delete':()=>store.remove(),'ripple-delete':()=>store.remove([...store.selection],true),'duplicate':()=>store.duplicate(),
 'snap':()=>{timeline.snap=!timeline.snap;$('#snap-button').classList.toggle('active',timeline.snap);},
 'zoom-in':()=>timeline.setZoom(timeline.zoom*1.2),'zoom-out':()=>timeline.setZoom(timeline.zoom/1.2),'fit':()=>timeline.setZoom((timeline.scroll.clientWidth-30)/duration(store.project)),
 'marker':()=>{store.addMarker(playback.time,'Marker '+(store.project.markers.length+1));toast('Marker added at '+timecode(playback.time,store.project.fps));},
 'add-title':addTitle,'append':()=>appendMedia(),'import':()=>$('#file-input').click(),'open-project':()=>$('#project-input').click(),
 'save':saveProject,'projects':projectsDialog,'collaborate':collaborate,'deliver':()=>setPage('deliver'),'settings':settings,
 'effects':()=>{poolMode=poolMode==='effects'?'media':'effects';if(page==='deliver')setPage('edit');renderMedia();$('#workspace').classList.add('show-media-mobile');},
 'markers':()=>{poolMode=poolMode==='markers'?'media':'markers';if(page==='deliver')setPage('edit');renderMedia();},
 'mixer':()=>setPage(page==='audio'?'edit':'audio'),
 'toggle-media':()=>{if(innerWidth<581)$('#workspace').classList.toggle('show-media-mobile');else $('#workspace').classList.toggle('no-media');$('#media-toggle').classList.toggle('active');timeline.render();},
 'toggle-inspector':()=>{if(innerWidth<=850)$('#workspace').classList.toggle('inspector-mobile');else $('#workspace').classList.toggle('no-inspector');$('#inspector-toggle').classList.toggle('active');timeline.render();},
 'media-view':()=>{mediaView=mediaView==='grid'?'list':'grid';renderMedia();},
 'source-play':()=>{playback.pause();sourcePlaying=!sourcePlaying;sourceLast=performance.now();},
 'source-prev':()=>{sourceTime=0;drawSource();},'source-in':()=>{sourceIn=sourceTime;if(sourceOut<=sourceIn)sourceOut=(store.project.media.find(m=>m.id===sourceId)?.duration||8);drawSource();},'source-out':()=>{if(sourceTime<=sourceIn){toast('Out point must follow the in point');return;}sourceOut=sourceTime;drawSource();},
 'fullscreen':()=>document.fullscreenElement?document.exitFullscreen():$('.program-screen').requestFullscreen(),
 'snapshot':async()=>{renderer.render(store.project,playback.time,false);const b=await renderer.snapshot();download(b,'veyra-frame-'+timecode(playback.time,store.project.fps).replaceAll(':','-')+'.png');},
 'reset-clip':()=>{const c=selected();if(c)store.updateClip(c.id,{scale:1,x:0,y:0,rotation:0,opacity:1,speed:1,gain:1,pan:0,fadeIn:0,fadeOut:0,keyframes:{},grade:gradeDefaults(),effects:[]});},
 'reset-grade':()=>{const c=activeSelected();if(c)store.updateClip(c.id,{grade:gradeDefaults()});},
 'clear-effects':()=>{const c=selected();if(c)store.updateClip(c.id,{effects:[],fadeIn:0,fadeOut:0});},
 'rename':()=>dialog('Rename project',`<label>Project name</label><input id="rename-value" value="${esc(store.project.name)}" maxlength="200">`,'<button data-action="close-dialog">Cancel</button><button class="primary" data-action="apply-rename">Rename</button>'),
 'apply-rename':()=>{const name=$('#rename-value').value.trim();if(name)store.transact('Rename project',p=>p.name=name);$('#dialog').close();},
 'apply-settings':()=>{const [width,height]=$('#settings-size').value.split('x').map(Number),fps=Number($('#settings-fps').value),name=$('#settings-name').value.trim(),theme=$('#settings-theme').value;store.transact('Project settings',p=>Object.assign(p,{width,height,fps,name:name||p.name}));const pw=Number($('#preview-quality').value);renderer.resize(pw,Math.round(pw*height/width));document.body.dataset.theme=theme;localStorage.setItem('veyra-theme',theme);$('#dialog').close();playback.invalidate();},
 'new-project':()=>dialog('New project','<label>Project name</label><input id="new-name" value="Untitled project"><p>Save or download your current project before starting a new one.</p>','<button data-action="export-project">Download current</button><button class="primary" data-action="create-new">Create new</button>'),
 'create-new':()=>{const name=$('#new-name').value.trim();sync.id=null;sync.dispose();sync.base=null;sync.pendingMedia.clear();playback.pause();store.replace(newProject(name||'Untitled project'));localStorage.removeItem(lastProjectKey);playback.seek(0);$('#dialog').close();renderMedia();},
 'export-project':()=>{const p=clone(store.project);for(const m of p.media)if(m.url?.startsWith('blob:')){m.url='';m.needsRelink=true;}download(JSON.stringify(p,null,2),p.name.replace(/[^a-zA-Z0-9_-]/g,'_')+'.veyra');toast('Project downloaded. Media files remain separate.');},
 'export-edl':()=>{download(exportEDL(store.project),'timeline.edl','text/plain');toast('EDL exported: cuts and timing; effects are not included.');},
 'export-srt':()=>download(exportSRT(store.project),'subtitles.srt','text/plain'),
 'join':async()=>{const code=$('#join-code').value;await sync.join(code);localStorage.setItem(lastProjectKey,sync.id);$('#dialog').close();await library.preload(store.project);playback.seek(0);toast('Joined project');},
 'invite':async()=>{await sync.invite();await collaborate();},
 'post-comment':async()=>{const input=$('#comment-text'),text=input.value.trim();if(!text)return;await sync.comment(text,playback.time);input.value='';await collaborate();},
 'close-dialog':()=>$('#dialog').close(),
 'render':runRender,'cancel-render':()=>renderAbort?.abort(),'download-render':()=>{if(renderJob?.blob)download(renderJob.blob,renderJob.name+'.'+renderJob.extension);},
 'init-graph':()=>{addNode('Color');},
 'remove-node':()=>{store.transact('Remove node',p=>{const n=p.nodes.find(n=>n.id===selectedNode);if(!n||['MediaIn','MediaOut'].includes(n.type))return;for(const x of p.nodes)x.inputs=x.inputs.flatMap(i=>i===n.id?n.inputs:[i]);p.nodes=p.nodes.filter(x=>x.id!==n.id);validateGraph(p.nodes);});selectedNode=null;renderExtra();renderInspector();},
 'add-track':()=>dialog('Add timeline track','<label>Track name</label><input id="track-name" value="Video 2"><label>Track type</label><select id="track-type"><option value="video">Video / title</option><option value="audio">Audio</option></select>','<button data-action="close-dialog">Cancel</button><button class="primary" data-action="create-track">Add track</button>'),
 'create-track':()=>{const name=$('#track-name').value.trim()||'Track',type=$('#track-type').value;store.transact('Add track',p=>{const t={id:uid(),name,type,muted:false,locked:false,gain:1};if(type==='video')p.tracks.unshift(t);else p.tracks.push(t);});$('#dialog').close();},
 'review-conflict':()=>{if(!sync.conflict)return;dialog('Resolve concurrent edits',`<p>Both editors changed the same objects. Your current edits remain open.</p><p>${sync.conflict.conflicts.length} competing ${sync.conflict.conflicts.length===1?'change':'changes'}. Download your version before choosing which version to keep.</p>`,'<button data-action="export-project">Download my version</button><button data-action="use-remote">Use shared version</button><button class="primary" data-action="keep-local">Keep my version</button>');},
 'use-remote':()=>{const d=sync.conflict;if(!d)return;sync.applying=true;store.replace(d.project);sync.applying=false;sync.base=clone(d.project);sync.revision=d.revision;sync.dirty=false;sync.conflict=null;sync.setStatus('All changes saved');$('#dialog').close();},
 'keep-local':async()=>{const d=sync.conflict;if(!d)return;sync.base=clone(d.project);sync.revision=d.revision;sync.conflict=null;sync.dirty=true;await sync.save();$('#dialog').close();},
 'relink':()=>dialog('Relink source media',`<p>Choose a file to replace missing source media. Clip timings and edits are preserved.</p><div>${store.project.media.filter(m=>m.type!=='title').map(m=>`<div class="project-row"><span>${esc(m.name)}</span><button class="secondary" data-relink="${m.id}">Choose file</button></div>`).join('')}</div>`),
 'help':()=>dialog('Veyra Studio',`<p>A browser-native editing workspace. Import footage, build a timeline, grade your shots, mix audio, and render a video.</p><div class="shortcut-grid">${[['Play / pause','Space'],['Reverse / pause / forward','J / K / L'],['Selection / blade tool','A / B'],['Split at playhead','Ctrl / ⌘ B'],['Undo / redo','Ctrl / ⌘ Z / ⇧ Z'],['Delete / ripple delete','Delete / ⇧ Delete'],['Duplicate clips','Ctrl / ⌘ D'],['Select all clips','Ctrl / ⌘ A'],['Add marker','M'],['Toggle snapping','N'],['Step frame','← / →'],['Save project','Ctrl / ⌘ S']].map(([a,b])=>`<span>${a}</span><kbd>${b}</kbd>`).join('')}</div><p>Import uses your browser’s decoders. Cloud uploads accept files up to 100 MB. Video export records playback in real time. The sample is an animated still-image edit with an original ambient score.</p><p>Veyra is an independent implementation. It does not open proprietary project formats or provide feature parity with desktop post-production suites.</p>`,'<button data-action="relink">Relink media</button><button data-action="close-dialog" class="primary">Continue editing</button>'),
 'safe-guides':()=>{$('#safe-guides').hidden=!$('#safe-guides').hidden;}
};
const menuItems={file:[['New project','new-project',''],['Project library','projects',''],['Save project','save','⌘ S'],['Import media','import',''],['Open project file','open-project',''],['Export project','export-project',''],['Relink media','relink','']],edit:[['Undo','undo','⌘ Z'],['Redo','redo','⌘ ⇧ Z'],['Duplicate','duplicate','⌘ D'],['Delete','delete','⌫'],['Ripple delete','ripple-delete','⇧ ⌫']],timeline:[['Add track','add-track',''],['Add marker','marker','M'],['Split at playhead','split','⌘ B'],['Fit timeline','fit',''],['Toggle snapping','snap','N']],clip:[['Append source','append',''],['Add title','add-title',''],['Reset clip','reset-clip',''],['Snapshot','snapshot','']],workspace:[['Project settings','settings',''],['Safe area guides','safe-guides',''],['Toggle media pool','toggle-media',''],['Toggle inspector','toggle-inspector',''],['Collaboration','collaborate','']]};
let relinkId=null;
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b){if(!e.target.closest('#menu'))$('#menu').hidden=true;return;}try{if(b.dataset.menu){const name=b.dataset.menu,rect=b.getBoundingClientRect();$('#menu').innerHTML=menuItems[name].map(([label,action,key])=>`<button data-action="${action}">${label}<kbd>${key}</kbd></button>`).join('');$('#menu').style.left=rect.left+'px';$('#menu').hidden=false;return;}$('#menu').hidden=true;if(b.dataset.action){if(renderAbort&&!['cancel-render','close-dialog','download-render'].includes(b.dataset.action)){toast('Finish or cancel the active render first');return;}await actions[b.dataset.action]?.();}if(b.dataset.page)setPage(b.dataset.page);if(b.dataset.inspector){inspectorTab=b.dataset.inspector;renderInspector();}if(b.dataset.bin){bin=b.dataset.bin;$$('[data-bin]').forEach(x=>x.classList.toggle('selected',x===b));renderMedia();}if(b.dataset.media){sourcePlaying=false;sourceId=b.dataset.media;sourceTime=sourceIn=0;sourceOut=Math.min(8,store.project.media.find(m=>m.id===sourceId).duration||8);renderMedia();drawSource();}if(b.dataset.tool){timeline.tool=b.dataset.tool;$$('[data-tool]').forEach(x=>x.classList.toggle('active',x===b));}if(b.dataset.effect)applyEffect(b.dataset.effect);if(b.dataset.seek){playback.seek(Number(b.dataset.seek));}if(b.dataset.trackAction){const key={mute:'muted',solo:'solo',lock:'locked'}[b.dataset.trackAction];store.transact('Toggle track '+key,p=>{const t=p.tracks.find(t=>t.id===b.dataset.id);t[key]=!t[key];});}if(b.dataset.openProject){if(sync.dirty&&sync.id)await sync.save();await sync.open(b.dataset.openProject);localStorage.setItem(lastProjectKey,sync.id);$('#dialog').close();await library.preload(store.project);playback.seek(0);}if(b.dataset.addNode)addNode(b.dataset.addNode);if(b.dataset.node){selectedNode=b.dataset.node;renderExtra();renderInspector();}if(b.dataset.keyframe&&b.dataset.scope==='clip'){const c=selected(),key=b.dataset.keyframe;if(!c)return;store.transact('Add '+key+' keyframe',p=>{const clip=p.clips.find(x=>x.id===c.id);clip.keyframes[key]??=[];const t=clamp(playback.time-c.start,0,c.duration);clip.keyframes[key]=clip.keyframes[key].filter(k=>Math.abs(k.time-t)>1/p.fps);clip.keyframes[key].push({time:t,value:clip[key]});});toast('Keyframe added at playhead');}if(b.dataset.preset){exportOptions.width=b.dataset.preset==='1080'?1920:1280;exportOptions.height=b.dataset.preset==='1080'?1080:720;renderDeliver();}if(b.dataset.removeMember){await sync.request({action:'removeMember',id:sync.id,userId:b.dataset.removeMember});await collaborate();}if(b.dataset.relink){relinkId=b.dataset.relink;$('#file-input').click();}}catch(err){toast(err.message);}});
document.addEventListener('dblclick',e=>{const card=e.target.closest('[data-media]');if(card)appendMedia(card.dataset.media);});
document.addEventListener('dragstart',e=>{const card=e.target.closest('[data-media]');if(card){e.dataTransfer.setData('application/veyra-media',card.dataset.media);e.dataTransfer.effectAllowed='copy';}});
$('#media-panel').addEventListener('dragover',e=>{e.preventDefault();$('#media-panel').classList.add('drop-target');});$('#media-panel').addEventListener('dragleave',()=>$('#media-panel').classList.remove('drop-target'));$('#media-panel').addEventListener('drop',e=>{e.preventDefault();$('#media-panel').classList.remove('drop-target');if(e.dataTransfer.files.length)importFiles(e.dataTransfer.files);});
$('#file-input').addEventListener('change',async e=>{if(relinkId&&e.target.files[0]){try{const file=e.target.files[0],fresh=await library.metadata(file),id=relinkId;fresh.id=id;const old=library.entries.get(id);old?.element?.pause?.();library.entries.delete(id);sync.pendingMedia.set(id,file);store.transact('Relink media',p=>{const m=p.media.find(m=>m.id===id);Object.assign(m,fresh,{id});delete m.needsRelink;});await library.load(fresh);$('#dialog').close();toast('Media relinked');}catch(err){toast(err.message);}finally{relinkId=null;}}else await importFiles(e.target.files);e.target.value='';});
$('#project-input').addEventListener('change',async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>5000000)throw Error('Project file exceeds 5 MB');const p=sanitizeMedia(validateProject(JSON.parse(await file.text())),{assetBase,browser:browserMode});sync.dispose();sync.id=null;sync.base=null;sync.pendingMedia.clear();playback.pause();store.replace(p);localStorage.removeItem(lastProjectKey);await library.preload(p);playback.seek(0);toast('Project opened. Relink missing source media from the File menu.');}catch(err){toast(err.message);}e.target.value='';});
$('#media-search').addEventListener('input',renderMedia);$('#timeline-zoom').addEventListener('input',e=>timeline.setZoom(e.target.value));
document.addEventListener('change',e=>{try{const target=e.target,key=target.dataset.property,scope=target.dataset.scope;if(key){const c=activeSelected();if(!c)return;const value=clamp(target.value,Number(target.min),Number(target.max));store.transact('Adjust '+key,p=>{const clip=p.clips.find(x=>x.id===c.id);if(scope==='grade'){clip.grade??=gradeDefaults();clip.grade[key]=value;}else if(scope==='track')p.tracks.find(t=>t.id===clip.trackId)[key]=value;else if(scope==='node'){const n=p.nodes.find(n=>n.id===selectedNode);if(n){n.params??={};n.params[key]=value;}}else{if(key==='speed'){const m=p.media.find(m=>m.id===clip.mediaId);if(['video','audio'].includes(m.type))clip.duration=Math.min(clip.duration,(m.duration-clip.in)/value);}clip[key]=value;if(clip.keyframes?.[key]?.length){const at=clamp(playback.time-clip.start,0,clip.duration);clip.keyframes[key]=clip.keyframes[key].filter(k=>Math.abs(k.time-at)>1/p.fps);clip.keyframes[key].push({time:at,value});}}});}if(target.dataset.trackGain){store.transact('Track gain',p=>p.tracks.find(t=>t.id===target.dataset.trackGain).gain=Number(target.value));}if(target.id==='master-gain'){library.masterGain=Number(target.value);if(library.master)library.master.gain.value=library.masterGain;}if(target.id==='preview-quality'){const w=Number(target.value);renderer.resize(w,Math.round(w*store.project.height/store.project.width));playback.invalidate();}if(target.dataset.nodeEnabled){store.transact('Toggle node',p=>p.nodes.find(n=>n.id===target.dataset.nodeEnabled).enabled=target.checked);}if(['title-text','title-font','title-size','title-color'].includes(target.id)){const c=selected();if(c)store.transact('Edit title',p=>{const m=p.media.find(m=>m.id===c.mediaId);const key={'title-text':'text','title-font':'fontFamily','title-size':'fontSize','title-color':'color'}[target.id];m[key]=key==='fontSize'?clamp(target.value,10,300):target.value;});}}catch(err){toast(err.message);}});
document.addEventListener('input',e=>{const t=e.target;if(t.dataset.property&&t.type==='range'){const pair=t.parentElement.querySelector('input[type=number]');if(pair)pair.value=t.value;}});
document.addEventListener('pointerdown',e=>{const wheel=e.target.closest('[data-wheel]');if(!wheel)return;const c=activeSelected();if(!c)return;const key=wheel.dataset.wheel,input=wheel.nextElementSibling,start=Number(input.value),x=e.clientX;const move=ev=>{input.value=clamp(start+(ev.clientX-x)/150,Number(input.min),Number(input.max));};const up=()=>{window.removeEventListener('pointermove',move);input.dispatchEvent(new Event('change',{bubbles:true}));};window.addEventListener('pointermove',move);window.addEventListener('pointerup',up,{once:true});});
document.addEventListener('keydown',e=>{if(e.target.closest('input,textarea,select')||$('#dialog').open||renderAbort)return;const mod=e.ctrlKey||e.metaKey,k=e.key.toLowerCase();let fn;if(mod&&k==='z')fn=e.shiftKey?'redo':'undo';else if(mod&&k==='s')fn='save';else if(mod&&k==='b')fn='split';else if(mod&&k==='d')fn='duplicate';else if(mod&&k==='a'){e.preventDefault();store.selection=new Set(store.project.clips.map(c=>c.id));store.dispatchEvent(new Event('selection'));renderInspector();return;}else if(k===' ')fn='play';else if(k==='delete'||k==='backspace')fn=e.shiftKey?'ripple-delete':'delete';else if(k==='arrowleft')fn='back';else if(k==='arrowright')fn='forward';else if(k==='home')fn='home';else if(k==='end')fn='end';else if(k==='m')fn='marker';else if(k==='n')fn='snap';else if(k==='a'||k==='b'){timeline.tool=k==='a'?'select':'blade';$$('[data-tool]').forEach(b=>b.classList.toggle('active',b.dataset.tool===timeline.tool));}else if(k==='k')playback.pause();else if(k==='j'||k==='l'){playback.rate=k==='j'?-1:1;playback.play().catch(err=>toast(err.message));}if(fn){e.preventDefault();Promise.resolve(actions[fn]()).catch(err=>toast(err.message));}});
store.addEventListener('change',()=>{$('#project-title').innerHTML=esc(store.project.name)+' <span>⌄</span>';$('#duration-label').textContent=timecode(duration(store.project),store.project.fps);$('#viewer-overlay').textContent=`${store.project.height}p · ${store.project.fps}`;if(page!=='deliver')renderMedia();renderInspector();renderExtra();playback.invalidate();});store.addEventListener('selection',renderInspector);
playback.addEventListener('frame',()=>{$('#timecode').textContent=timecode(playback.time+3600,store.project.fps);const level=playback.playing?clamp(library.meter()*250,0,100):0;$('#meter-l').style.height=level+'%';$('#meter-r').style.height=level*.96+'%';if(page==='color')drawScopes();});playback.addEventListener('state',()=>{$('#play').textContent=playback.playing?'Ⅱ':'▶';if(!playback.playing){$('#meter-l').style.height='0';$('#meter-r').style.height='0';}});
sync.addEventListener('status',()=>{$('#save-status').textContent=sync.status;$('#save-status').style.cursor=sync.conflict?'pointer':'default';});sync.addEventListener('conflict',()=>toast('Concurrent edit detected. Click save status to review.'));$('#save-status').addEventListener('click',()=>{if(sync.conflict)actions['review-conflict']();else saveProject();});
window.addEventListener('beforeunload',e=>{if(sync.dirty||renderAbort){e.preventDefault();e.returnValue='';}});window.addEventListener('resize',()=>timeline.render());
if(document.modelContext?.registerTool){const lifecycle=new AbortController();const definitions=[{name:'read_timeline',description:'Read the current timeline clips, frame rate and playhead',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({name:store.project.name,fps:store.project.fps,clips:clone(store.project.clips),time:playback.time})},{name:'seek_timeline',description:'Move the visible playhead to a time in seconds',inputSchema:{type:'object',properties:{seconds:{type:'number',minimum:0}},required:['seconds'],additionalProperties:false},execute:input=>{if(!Number.isFinite(input.seconds)||input.seconds<0)throw Error('Invalid time');playback.pause();playback.seek(input.seconds);return {time:playback.time};}},{name:'split_selected_clips',description:'Split selected clips at the visible playhead; updates timeline history',inputSchema:{type:'object',properties:{},additionalProperties:false},execute:()=>{store.split(playback.time);return {clipCount:store.project.clips.length};}}];for(const tool of definitions)Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
store.select('clip-coast-01');renderMedia();renderInspector();renderExtra();drawSource();library.preload(store.project).then(()=>playback.invalidate());document.body.dataset.theme=localStorage.getItem('veyra-theme')||'dark';const lastProject=localStorage.getItem(lastProjectKey);if(lastProject){sync.open(lastProject).then(()=>library.preload(store.project)).then(()=>playback.seek(0)).catch(e=>toast('Could not reopen saved project: '+e.message));}
window.veyra={store,playback,renderer,library,sync,timeline};

document.addEventListener('veyra-renderer-changed',()=>{$('#engine-status').textContent=renderer.mode+' · GPU unavailable';playback.invalidate();});document.addEventListener('veyra-media-ready',()=>playback.invalidate());

document.addEventListener('pointerdown',e=>{if(renderAbort&&!e.target.closest('[data-action=cancel-render]')){e.preventDefault();e.stopImmediatePropagation();}},{capture:true});
